import { useState } from "react";
export default function App() {
  const [texte, setTexte] = useState("");
  const [statut, setStatut] = useState("idle");
  async function envoyer(event) {
    event.preventDefault();
    if (!texte.trim()) { setStatut("error"); return; }
    setStatut("sending");
    await Promise.resolve(); // remplacez par un vrai appel et traitez son échec
    setStatut("success");
  }
  return <form onSubmit={envoyer}><label>Message<input value={texte} onChange={e => setTexte(e.target.value)} /></label>
    <button disabled={statut === "sending"}>Envoyer</button><p role="status">{statut}</p></form>;
}

